-- Wirlem (443010) -- Loping Plains open-world raid encounter.
-- Generated by sof_content/gen_loping_rares.py -- do not hand-edit.
-- Page: adds spawn ~2 min after engage from the bleachers; three Hymn
-- types (spell auras pinned 9379/9380/9381); Touch of the Phantom charm
-- (9375) and Aria of Torpidity PBAE (9378) fire periodically.
-- Simplifications: adds cast their hymn on a timer (aura stand-in); the
-- "reaches Wirlem" buff/heal and ranged-only Remorse kill are not
-- scripted in v1. Wirlem's self-cleanse rides his innate abilities.

local BLEACHER = { x = 1710.0, y = 1260.0, z = 32.0 }

function event_combat(e)
	if e.joined then
		eq.set_timer("adds", 120000)
		eq.set_timer("phantom", 45000)
		eq.set_timer("aria", 60000)
	else
		eq.stop_all_timers()
	end
end

function event_timer(e)
	if e.timer == "adds" then
		eq.spawn2(443680, 0, 0, BLEACHER.x - 25, BLEACHER.y, BLEACHER.z, 0)
		eq.spawn2(443681, 0, 0, BLEACHER.x, BLEACHER.y, BLEACHER.z, 0)
		eq.spawn2(443682, 0, 0, BLEACHER.x + 25, BLEACHER.y, BLEACHER.z, 0)
	elseif e.timer == "phantom" then
		local t = e.self:GetTarget()
		if t ~= nil and t:IsClient() then
			e.self:CastSpell(9375, t:GetID())
		end
	elseif e.timer == "aria" then
		e.self:CastSpell(9378, e.self:GetID())
	end
end

function event_death_complete(e)
	eq.stop_all_timers()
end
